CREATE TABLE "access_grants" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"grant_number" integer GENERATED BY DEFAULT AS IDENTITY (sequence name "access_grants_grant_number_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 2147483647 START WITH 1 CACHE 1),
	"name" text,
	"person_id" uuid,
	"admin_user_id" uuid,
	"service_id" uuid NOT NULL,
	"level_key" text,
	"status_key" text,
	"resource_scope" text,
	"granted_on" date,
	"revoked_on" date,
	"expires_on" date,
	"archived_at" timestamp with time zone,
	"archived_by_id" uuid,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "access_grants_name_length" CHECK ("access_grants"."name" is null or length(btrim("access_grants"."name")) between 1 and 200),
	CONSTRAINT "access_grants_scope_length" CHECK ("access_grants"."resource_scope" is null or length("access_grants"."resource_scope") <= 1000),
	CONSTRAINT "access_grants_revoked_after_granted" CHECK ("access_grants"."granted_on" is null or "access_grants"."revoked_on" is null or "access_grants"."granted_on" <= "access_grants"."revoked_on"),
	CONSTRAINT "access_grants_expires_after_granted" CHECK ("access_grants"."granted_on" is null or "access_grants"."expires_on" is null or "access_grants"."granted_on" <= "access_grants"."expires_on")
);
